        raise TypeError("Could not convert nanoseconds to a time value")
    # If tz is None, use the default timezone
    if tz is None:
        tz = default_timezone
    # Return a formatted time string
    return tz.utcfromtimestamp(seconds + (micros / 1000000)).strftime("%Y-%m-%d %H:%M:%S.%f")

