        raise ValueError("Metadata should be a dictionary")
    if timeout is not None and not isinstance(timeout, (float, int)) and timeout < 0:
        raise ValueError("Timeout should be a positive number or None")

    def decorator(func):
        def execute_with_timeout(tx, *args, **kwargs):
            try:
                tx.metadata = metadata
                result = func(tx, *args, **kwargs)
            except Exception as e:
                tx.rollback()
                raise e
            else:
                if timeout is not None:
                    tx.timeout = timeout
                return result
        return execute_with_timeout
    return decorator

