    # Retrieve the values from the record
    values = self._values

    # Initialize the output dictionary
    output = {}

    # Handle the no keys case
    if not keys:
        # Add all values to the output dictionary, keyed by field name
        for field in self._fields:
            output[field] = values[self._fields.index(field)]
    else:
        # Loop through the provided keys and include their values in the output dictionary
        for key in keys:
            # Check if the key is an index
            if isinstance(key, int):
                # Verify that the index is within bounds
                if key < 0 or key >= len(values):
                    # Raise an IndexError if the index is out of bounds
                    raise IndexError(f"Index {key} is out of bounds for record with {len(values)} values")
                # Add the value at the specified index to the output dictionary, keyed by field name
                output[self._fields[key]] = values[key]
            else:
                # Check if the key is a field name
