                    # Raise an IndexError if the key is not a field name
                    raise IndexError(f"Key {key} does not correspond to a field in record with fields {self._fields}")
                # Add the value associated with the field name to the output dictionary
                output[key] = values[self._fields.index(key)]

    # Return the output dictionary
    return output

