def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    # If the number of records to discard is not specified, discard all
    # records from the last query by default
    if n == -1:
        n = len(self.last_query)

    # Appends a DISCARD message to the output queue
    queue_msg = {"DISCARD": {"n": n, "qid": qid, "dehydration_hooks": dehydration_hooks, "hydration_hooks": hydration_hooks}}
    self.output_queue.append(queue_msg)

    # Returns a Response object with the given handlers registered
    return self.Response(handlers)

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    # Checking for invalid input
    if n is not int:
        raise TypeError("The number of records to discard must be a positive integer.")
    if n < 1:
        raise ValueError("The number of records to discard must be a positive integer.")
    if qid is not int:
        raise TypeError("The query ID to discard for must be a positive integer.")
    if qid < 1:
        raise ValueError("The query ID to discard for must be a positive integer.")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("The dehydration hooks must be a dictionary from type to dehydration function.")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("The hydration hooks must be a dictionary from type to hydration function.")
    if handlers is not None and not isinstance(handlers, dict):
        raise TypeError("The handlers must be a dictionary from handler to function.")
    # Checking for valid number of records
    if n > len(self.buffer):
        raise ValueError("Number of records to discard exceeds buffer size.")
    # Checking for valid query ID
    if qid > len(self.queries):
        raise ValueError("Query ID to discard for does not exist.")
    # Discarding records
    self.buffer = self.buffer[:qid]
    # Dehydrating records
    for record in self.buffer:
        if dehydration_hooks is not None and isinstance(record, dict):
            record['metadata'] = dehydration_hooks[type(record['metadata'])](record['metadata'])
        if hydration_hooks is not None and isinstance(record, dict):
            record['payload'] = hydration_hooks[type(record['payload'])](record['payload'])
    # Hydrating records and appending to output queue
    for record in self.buffer:
        response = self.handler_queue[self.queries[qid]]
        record = hydration_hooks[type(record)](record)
        response.append(record)
    # Returning output queue
    return response

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    try:
        n = int(n)
        if n < 0:
            raise ValueError("N must be a positive integer")
        qid = int(qid)
        if qid < 0:
            raise ValueError("QID must be a positive integer")
        if dehydration_hooks and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary")
        if hydration_hooks and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary")
        if not all(
            isinstance(dehydration_hook, Callable)
            for dehydration_hook in dehydration_hooks.values()
        ):
            raise TypeError("dehydration_hooks must only contain callable values")
        if not all(
            isinstance(hydration_hook, Callable)
            for hydration_hook in hydration_hooks.values()
        ):
            raise TypeError("hydration_hooks must only contain callable values")
    except TypeError as e:
        raise TypeError("Invalid parameters provided") from e
    except ValueError as e:
        raise ValueError("Invalid parameters provided") from e

    discard_message = Message(DISCARD, {"n": n, "qid": qid})
    self._outgoing.append(discard_message)
    return Response(self, handlers=handlers)

