    if n is not int:
        raise TypeError("The number of records to discard must be a positive integer.")
    if n < 1:
        raise ValueError("The number of records to discard must be a positive integer.")
    if qid is not int:
        raise TypeError("The query ID to discard for must be a positive integer.")
    if qid < 1:
        raise ValueError("The query ID to discard for must be a positive integer.")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("The dehydration hooks must be a dictionary from type to dehydration function.")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("The hydration hooks must be a dictionary from type to hydration function.")
    if handlers is not None and not isinstance(handlers, dict):
        raise TypeError("The handlers must be a dictionary from handler to function.")
    # Checking for valid number of records
    if n > len(self.buffer):
        raise ValueError("Number of records to discard exceeds buffer size.")
    # Checking for valid query ID
    if qid > len(self.queries):
        raise ValueError("Query ID to discard for does not exist.")
    # Discarding records
    self.buffer = self.buffer[:qid]
    # Dehydrating records
    for record in self.buffer:
        if dehydration_hooks is not None and isinstance(record, dict):
            record['metadata'] = dehydration_hooks[type(record['metadata'])](record['metadata'])
        if hydration_hooks is not None and isinstance(record, dict):
            record['payload'] = hydration_hooks[type(record['payload'])](record['payload'])
