def format(sql, params):
    if isinstance(params, dict):
        out_params = []
        for key, value in params.items():
            out_params.append(f"{key}={value}")
        return sql % tuple(out_params)
    elif isinstance(params, (list, tuple)):
        out_params = {}
        for i, value in enumerate(params):
            out_params[f"{i + 1}"] = value
        return sql, out_params
    else:
        raise ValueError("params must be a dict or a sequence")

def format(self, sql, params):
    # Initialize the out-style parameters
    out_params = {}

    # Check if the parameters are a mapping
    if isinstance(params, Mapping):
        # Iterate over the parameters
        for param in params:
            # Check if the parameter is a string or integer
            if isinstance(param, str) or isinstance(param, int):
                # Convert the parameter to an out-style parameter
                out_param = "{" + param + "}"
                out_params[out_param] = params[param]
            else:
                # Raise a TypeError if the parameter is not a string or integer
                raise TypeError("Invalid parameter type")
    # Check if the parameters are a sequence
    elif isinstance(params, Sequence):
        # Iterate over the parameters
        for idx, param in enumerate(params):
            # Convert the parameter to an out-style parameter
            out_param = "{" + str(idx) + "}"
            out_params[out_param] = param
    else:
        # Raise a TypeError if the parameters are not a mapping or sequence
        raise TypeError("Invalid parameters type")

    # Format the SQL query
    formatted_sql = sql.format(**out_params)

    return formatted_sql, out_params

