def check_digests_present_and_used(manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Verify that the manifest files and digests used are valid
    if not manifest_files or not digests_used:
        raise ValueError("Manifest files and digests used are required")

    # Iterate through each manifest file and verify that all digests in the needed field are present and used
    for manifest_file in manifest_files:
        for digest in manifest_file["needed"]:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in any manifest file")
