        raise TypeError("Fixity must be a dictionary.")

    # Check if manifest_files is a list
    if not isinstance(manifest_files, list):
        raise TypeError("Manifest_files must be a list.")

    # Create a list of valid and invalid files
    for file in manifest_files:
        if isinstance(file, str):
            valid_manifest_files.append(file)
        else:
            invalid_manifest_files.append(file)

    # Check if all manifest files have a corresponding checksum in fixity
    for file in valid_manifest_files:
        if file not in fixity:
            raise KeyError(f"Missing checksum for {file}.")

    # Check if fixity contains any unexpected files
    for file in fixity:
        if file not in valid_manifest_files:
            raise ValueError(f"Unexpected file {file} found in fixity.")

    # Check if all checksums are in hexadecimal format
