def absorb(self, args):
    if not args:
        return []
    result = []
    for i in range(0, len(args) - 1):
        if args[i].is_neg_atom() and args[i + 1].is_neg_atom():
            continue
        if args[i].is_atom() and args[i + 1].is_atom():
            if args[i].is_neg_atom() or args[i + 1].is_neg_atom():
                if args[i].variables == args[i + 1].variables:
                    result.append(args[i].copy(atom=args[i].atom.and_op(args[i + 1].atom)))
                else:
                    result.append(args[i])
                    result.append(args[i + 1])
            else:
                if args[i].variables == args[i + 1].variables:
                    result.append(args[i].copy(atom=args[i].atom.or_op(args[i + 1].atom)))
                else:
                    result.append(args[i])
                    result.append(args[i + 1])
        elif args[i].is_atom() and not args[i + 1].is_atom():
            if args[i].is_neg_atom():
                if args[i + 1].variables == args[i].variables:
                    result.append(args[i].copy(atom=args[i].atom.and_op(args[i + 1].atom)))
                else:
                    result.append(args[i + 1])
            else:
                if args[i + 1].variables == args[i].variables:
                    result.append(args[i].copy(atom=args[i].atom.or_op(args[i + 1].atom)))
                else:
                    result.append(args[i])
