    if not pieces:
        raise ValueError("Must provide at least one version piece")
    if not style:
        raise ValueError("Must provide a style")

    rendered = []
    for piece in pieces:
        if style == "bold":
            rendered.append("<b>{}</b>".format(piece))
        elif style == "italic":
            rendered.append("<i>{}</i>".format(piece))
        elif style == "underline":
            rendered.append("<u>{}</u>".format(piece))
        else:
