        raise TypeError("params must be of type dict")
    if type(bug_ids) != list:
        raise TypeError("bug_ids must be of type list")
    if len(bug_ids) == 0:
        raise ValueError("bug_ids must not be empty")
    for bug_id in bug_ids:
        if type(bug_id) not in (int, str):
            raise TypeError("bug_id must be of type int or str")
    if "id" in params and type(params["id"]) == list:
        params["id"].extend(bug_ids)
    else:
        params["id"] = bug_ids
    return params

def amend_bzparams(self, params, bug_ids):
    # Ensure that the params and bug_ids are lists
    if not isinstance(params, list):
        raise ValueError("params must be a list")
    if not isinstance(bug_ids, list):
        raise ValueError("bug_ids must be a list")

    # Ensure that the bug_ids are integers
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise ValueError(f"{bug_id} is not a valid bug ID")

    # Ensure that the params list has at least one bug ID
    if not any("bug_id" in param for param in params):
        raise ValueError("params must include at least one bug ID")

    # Create a dictionary to store the updated params
    updated_params = {}

    # Loop through the params list and update the bug IDs
    for i, param in enumerate(params):
        if "bug_id" in param:
            # Get the current bug ID
            current_bug_id = param["bug_id"]

            # Check if the current bug ID is in the bug_ids list
            if current_bug_id in bug_ids:
                # Update the bug ID with the new ID
                updated_params["bug_id"] = bug_ids[bug_ids.index(current_bug_id)]
            else:
                # If the current bug ID is not in the list, raise an error
                raise ValueError(f"{current_bug_id} is not a valid bug ID")

        # Add the rest of the params to the updated params dict
        for k, v in param.items():
            if k != "bug_id":
                updated_params[k] = v

    return updated_params

