def paging(response, max_results):
    def generate_pages():
        page = []
        for item in response:
            page.append(item)
            if len(page) == max_results:
                yield page
                page = []
        if page:
            yield page

    return generate_pages()

def paging(response, max_results):
    i = 0
    done = False
    while not done:
        page = []
        for _ in range(max_results):
            if i >= len(response):
                done = True
                break
            page.append(response[i])
            i += 1
        yield page

