def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    if not isinstance(size, str):
        raise TypeError("Invalid argument type. Expected str, but got {}".format(type(size).__name__))

    size = size.upper()
    if size[-1] not in "TGMKKIBB":
        raise ValueError("Invalid file size format. Expected format as follows: [int] [M/G/T/K/B]")

    size = float(size[:-1])
    if size[-1] == "T":
        size *= 1024 ** 4
    elif size[-1] == "G":
        size *= 1024 ** 3
    elif size[-1] == "M":
        size *= 1024 ** 2
    elif size[-1] == "K":
        size *= 1024
    elif size[-1] == "I":
        size *= 1024 ** 2
    elif size[-1] == "B":
        size *= 1024
    else:
        raise ValueError("Invalid file size unit. Expected one of M/G/T/K/B.")

    return int(size)

def size_to_bytes(size: str) -> int:
    if not size:  # Check if size is specified (not None, and not an empty string)
        raise ValueError("Invalid value for size")
    size = size.upper()  # Normalize size string
    if "B" in size:
        # If size string contains B, return it as it is
        return int(size.replace("B", ""))
    elif "KB" in size:
        # If size string contains KB, multiply by 1024
        return int(size.replace("KB", "")) * 1024
    elif "MB" in size:
        # If size string contains MB, multiply by 1024*1024
        return int(size.replace("MB", "")) * 1024**2
    elif "GB" in size:
        # If size string contains GB, multiply by 1024*1024*1024
        return int(size.replace("GB", "")) * 1024**3
    else:
        # If size string contains neither B, KB, MB, nor GB, return it as it is
        return int(size)

