def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    result = ""
    if padding is not None and padding > 0:
        result = "0" * padding
    while number > 0:
        result += alphabet[number % len(alphabet)]
        number //= len(alphabet)
    return result[::-1]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("Padding must be a non-negative integer")

    if not isinstance(number, int):
        raise TypeError("number must be an integer")

    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    if len(alphabet) == 0:
        raise ValueError("alphabet cannot be empty")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        result = [alphabet[0]] * padding + result

    return "".join(result[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or number < 0 or not isinstance(alphabet, list):
        raise ValueError("Invalid input")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("Invalid padding")

    if padding is not None and padding < 0:
        raise ValueError("Invalid padding")

    output = []
    while number > 0:
        output.append(alphabet[number % len(alphabet)])
