def prepare_repository_from_archive(archive_path, filename=None, tmp_path='/tmp'):
    """Given an existing archive_path, uncompress it. Returns a file repo url which can be used as origin url.
    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"'{archive_path}' is not a valid file path")

    if filename and not os.path.isfile(filename):
        raise FileNotFoundError(f"'{filename}' is not a valid file path")

    if not os.path.isdir(tmp_path):
        raise NotADirectoryError(f"'{tmp_path}' is not a valid directory path")

    if not tarfile.is_tarfile(archive_path):
        raise ValueError(f"'{archive_path}' is not a tar file")

    with tarfile.open(archive_path, filename) as tar:
        out_path = os.path.join(tmp_path, os.path.basename(tar.name))
        if os.path.exists(out_path):
            raise FileExistsError(f"'{out_path}' already exists")
        tar.extractall(out_path)

    repo_url = f"file://{out_path}"
    return repo_url

def prepare_repository_from_archive(archive_path, filename=None, tmp_path='/tmp'):
    if not os.path.isfile(archive_path):
        raise FileNotFoundError("Specified archive file does not exist!")
    if filename is None:
        filename = os.path.basename(archive_path)
    tar = subprocess.Popen(f'tar -xzf {archive_path} -C {tmp_path}', shell=True)
    tar.wait()
    repo_url = os.path.join(tmp_path, filename)
    return repo_url

