def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any containing directories as needed. But if the file already exists and overwrite is False, abort before writing anything.
    '''
    try:
        # Create any containing directories if needed
        if not os.path.exists(os.path.dirname(config_filename)):
            os.makedirs(os.path.dirname(config_filename))

        # Check if file already exists and overwrite is False
        if os.path.exists(config_filename) and not overwrite:
            raise ValueError("File already exists and overwrite is False")

        # Write the file using mode and rendered config
        with open(config_filename, "a+" if os.path.exists(config_filename) else "w", encoding="utf-8") as f:
            f.write(rendered_config.decode("utf-8"))
    except FileNotFoundError:
        # Catch file not found error and raise ValueError
        raise ValueError("Invalid target file path")
    except ValueError as e:
        # Catch value error and re-raise
        raise ValueError(str(e)) from None
    except Exception as e:
        # Catch all other exceptions and re-raise
        raise Exception(f"Error writing configuration to file: {e}") from None

