    try:
        import subprocess
        import inspect
        func_source = inspect.getsource(func)
        function_name = func.__name__
        if extra_env:
            subprocess_env = {**os.environ, **extra_env}
        else:
            subprocess_env = os.environ
        subprocess.run(
            ["python", "-c", func_source, "-m", function_name, *args],
            timeout=timeout,
            env=subprocess_env,
