def run_command(command, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command with the specified arguments. If cwd is provided, use it as the working directory. If verbose is true, print the command and its output. If hide_stderr is true, suppress output to stderr. Return the output of the command. If there is an error, throw a Python exception."""
    args = args if args else []
    if env:
        env = env.copy()
    else:
        env = {}
    if cwd:
        env["PWD"] = cwd
    cmd = [command] + args
    process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    out, err = process.communicate()
    if process.returncode != 0 and not hide_stderr:
        raise subprocess.CalledProcessError(process.returncode, cmd, output=out)
    if verbose:
        print(cmd)
        print(out.decode())
    return out.decode()

def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):

    if isinstance(commands, str):
        commands = [commands]

    if args is None:
        args = []

    if cwd is None:
        cwd = os.getcwd()

    if verbose:
        print(f"Running command '{commands}' with args '{args}' in '{cwd}'...")

    if env is not None:
        for k, v in env.items():
            os.environ[k] = v

    try:
        proc = subprocess.run(commands, cwd=cwd, check=True, capture_output=True)
        output = proc.stdout.strip()
        err = proc.stderr.strip()

        if verbose:
            print(f"stdout: {output!r}")
            if hide_stderr:
                print("stderr is suppressed")
            else:
                print(f"stderr: {err!r}")

        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, commands, output=output, stderr=err)

        return output

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command '{commands}' failed with exit code '{e.returncode}'")
        raise
    except Exception as e:
        if verbose:
            print(f"Other error occurred in command '{commands}': {e}")
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
