def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Set[rdflib.Node] = None):
    """
    Find the roots in some sort of transitive hierarchy.

    >>> find_roots(graph, rdflib.RDFS.subClassOf)
    {<rdflib.term.URIRef('http://www.w3.org/2000/01/rdf-schema#Class')}

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    # Initialize the set of roots
    if roots is None:
        roots = set(graph.subjects(predicate=prop))

    # Traverse the graph to find new roots
    for s, _, o in graph.triples((None, prop, None)):
        # If the subject (s) is not already a root
        if s not in roots:
            # Check if the object (o) is a root
            if o in roots:
                # Add the subject to the set of roots
                roots.add(s)

    return roots

def find_roots(graph: rdflib.Graph, prop: Union[rdflib.URIRef, rdflib.BNode], roots: Optional[Set[rdflib.URIRef]] = None) -> Set[rdflib.URIRef]:
    """Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf) will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for s, o in graph.subject_objects(prop):
        if s not in roots:
            roots.add(s)
    return roots

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    if roots is None:
        roots = set()
    for s, o in graph[None:prop]:
        if s not in roots:
            roots.add(s)
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(prop):
        if child not in roots:
