    try:
        doc_root = etree.fromstring(doc)
    except ParseError:
        raise ValueError("Invalid XML document")
    try:
        parent_cert = etree.fromstring(doc_root.find("ParentCertificate"))
    except ParseError:
        raise ValueError("ParentCertificate element not found")
    if parent_cert.get("Signature") != signature:
        raise ValueError("Invalid signature")
    return True

def verify_relayable_signature(public_key, doc, signature):
    try:
        # Verify that the signature is valid
        verified = public_key.verify(doc, signature)

        # If the signature is not valid, raise an exception
        if not verified:
            raise Exception("Signature validation failed")
    except Exception as e:
        # If an exception occurs during validation, raise an exception
        raise Exception("Error during signature validation: " + str(e))

    # If the signature is valid, return True
    return True

