def parse_diaspora_webfinger(document: str) -> Dict:
    if not document:
        raise ValueError("Invalid document: {}".format(document))
    try:
        doc_json = json.loads(document)
    except json.JSONDecodeError:
        doc_xml = ET.fromstring(document)
        doc_json = {"result": {}, "err": "not JSON"}
        for elt in doc_xml:
            if elt.tag == "Subject":
                doc_json["result"]["subject"] = elt.text
        if not doc_json["result"]:
            raise ValueError("Could not parse Diaspora webfinger")
    return doc_json[0]

